write: {"content": "import csv
import json
import argparse
import sys

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--json', action='store_true', help='выводить только JSON')
    parser.add_argument('path', nargs='?', default='компоненты.csv')
    args = parser.parse_args()
    allowed_licenses = {
        'MIT', 'BSD-3-Clause', 'Apache-2.0', 'Public Domain', 'Проприетарная'
    }
    allowed_count = 0
    needs_review_count = 0

    path = args.path
    with open(path, 'r', encoding='utf-8', newline='') as f:
        reader = csv.reader(f, delimiter=';')
        header = next(reader, None)
        if header is None:
            if args.json:
                print(json.dumps({"допустимо": 0, "требует_проверки": 0}, ensure_ascii=False))
            else:
                print('Итого: допустимо — 0, требует проверки — 0')
            return
        for row in reader:
            if not row:
                continue
            if len(row) < 2:
                continue
            component = row[0].strip()
            license_ = row[1].strip()
            if license_ in allowed_licenses:
                status = 'допустима'
                allowed_count += 1
            else:
                status = 'требует проверки'
                needs_review_count += 1
            print(f'{component} — {license_} — {status}')

    if args.json:
        print(json.dumps({"допустимо": allowed_count, "требует_проверки": needs_review_count}, ensure_ascii=False))
    else:
        print(f'Итого: допустимо — {allowed_count}, требует проверки — {needs_review_count}')

if __name__ == '__main__':
    main()
